def weighted_adjacency(n, edges, directed):
    adjacency = []
    for vertex in range(n):
        adjacency.append([])
    for edge in edges:
        source = edge[0]
        target = edge[1]
        weight = edge[2]
        adjacency[source].append([target, weight])
        if not directed:
            adjacency[target].append([source, weight])
    return adjacency

def path_weight(adjacency, path):
    if len(path) == 0:
        return None
    for vertex in path:
        if vertex < 0 or vertex >= len(adjacency):
            return None
    total = 0
    for i in range(1, len(path)):
        found = False
        for edge in adjacency[path[i - 1]]:
            if edge[0] == path[i]:
                total = total + edge[1]
                found = True
        if not found:
            return None
    return total

